import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.CWpttWmj.js";const u=JSON.parse('{"title":"Claiming a name","description":"","frontmatter":{},"headers":[],"relativePath":"guide/claiming.md","filePath":"guide/claiming.md","lastUpdated":null}'),i={name:"guide/claiming.md"};function n(s,e,d,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="claiming-a-name" tabindex="-1">Claiming a name <a class="header-anchor" href="#claiming-a-name" aria-label="Permalink to &quot;Claiming a name&quot;">​</a></h1><p>&quot;Claiming&quot; covers the cases where the name you want isn&#39;t simply free: it&#39;s expired, it&#39;s in its grace period, or it&#39;s listed for sale. Each needs a different move.</p><h2 id="which-situation-are-you-in" tabindex="-1">Which situation are you in? <a class="header-anchor" href="#which-situation-are-you-in" aria-label="Permalink to &quot;Which situation are you in?&quot;">​</a></h2><p>Search for the name in the app and it tells you which of four states applies:</p><table tabindex="0"><thead><tr><th>What you see</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Available</strong></td><td>Nobody holds it</td><td><a href="/docs/guide/registering.html">Register it</a></td></tr><tr><td><strong>In grace period</strong></td><td>Expired, still locked to its old owner for 90 days</td><td>Wait for the release date shown</td></tr><tr><td><strong>Taken</strong></td><td>Actively registered</td><td><a href="#buying-a-name-someone-else-owns">Buy it</a>, or wait</td></tr><tr><td><strong>Not a usable name</strong></td><td>Fails validation</td><td>Pick another — see <a href="/docs/guide/registering.html#what-makes-a-name-valid">validity rules</a></td></tr></tbody></table><h2 id="claiming-a-name-in-its-grace-period" tabindex="-1">Claiming a name in its grace period <a class="header-anchor" href="#claiming-a-name-in-its-grace-period" aria-label="Permalink to &quot;Claiming a name in its grace period&quot;">​</a></h2><p>An expired name is <strong>not</strong> available. It stays reserved for its previous owner for 90 days after expiry, during which they can renew and keep it. Registration attempts revert with <code>taken</code>.</p><p>The app shows the exact date the name is released. To get it:</p><ol><li>Note the release date — <code>expiry + 90 days</code>.</li><li>Be ready at that moment. There is no queue, no auction, and no priority for anyone.</li><li>Run the ordinary <a href="/docs/guide/registering.html">commit-reveal registration</a>. First valid reveal wins.</li></ol><div class="warning custom-block"><p class="custom-block-title">Grace-period names are frequently renewed</p><p>Most names in grace get renewed by their owners — that is exactly what the grace period is for. Don&#39;t count on one being released. Have a second choice.</p></div><p>There is also no premium-decay auction on release, unlike some naming services. The price drops to the normal tier rate the instant the name frees up, which means popular releases are competitive.</p><h2 id="buying-a-name-someone-else-owns" tabindex="-1">Buying a name someone else owns <a class="header-anchor" href="#buying-a-name-someone-else-owns" aria-label="Permalink to &quot;Buying a name someone else owns&quot;">​</a></h2><p>A registered name can only be obtained from its owner. Two routes.</p><h3 id="it-s-listed-on-the-marketplace" tabindex="-1">It&#39;s listed on the marketplace <a class="header-anchor" href="#it-s-listed-on-the-marketplace" aria-label="Permalink to &quot;It&#39;s listed on the marketplace&quot;">​</a></h3><p>If the owner has listed it, the app shows a price and a <strong>Buy</strong> button. Settlement is atomic — the token moves to you and payment moves to the seller in one transaction. See <a href="/docs/guide/marketplace.html">Marketplace</a>.</p><h3 id="it-isn-t-listed" tabindex="-1">It isn&#39;t listed <a class="header-anchor" href="#it-isn-t-listed" aria-label="Permalink to &quot;It isn&#39;t listed&quot;">​</a></h3><p>Then you need the owner to agree. You can find them:</p><ul><li>In the app — the search result shows the current owner&#39;s address.</li><li>Via the API — <code>GET /api/v1/domains/:name</code> returns <code>owner</code>.</li></ul><p>Reach them through their <a href="/docs/guide/records.html">records</a> — many owners set an <code>email</code>, <code>com.twitter</code> or <code>url</code> record. Then either ask them to list it at an agreed price, or agree a direct transfer.</p><div class="danger custom-block"><p class="custom-block-title">Never pay for a name outside an atomic transaction</p><p>If you send funds first and trust the owner to transfer afterwards, you have no recourse when they don&#39;t. There is no escrow, no dispute process and no reversal.</p><p>Use a marketplace listing, where payment and transfer happen in the same transaction. If you must deal off-market, use a contract that swaps both sides atomically. &quot;Send me the money and I&#39;ll transfer it&quot; is how people get robbed. See <a href="/docs/safety.html#buying-a-name-safely">Safety</a>.</p></div><h2 id="after-you-claim-a-name" tabindex="-1">After you claim a name <a class="header-anchor" href="#after-you-claim-a-name" aria-label="Permalink to &quot;After you claim a name&quot;">​</a></h2><p>Whether you registered it fresh or bought it, do these in order.</p><p><strong>If you registered it</strong>, the controller has already bound a resolver and pointed the name at you. Nothing is required.</p><p><strong>If you bought or received it</strong>, two steps are mandatory and both are easy to forget:</p><ol><li><strong>Reclaim it</strong> — <code>registrar.reclaim(tokenId, yourAddress)</code>. Until you do, the previous owner is still the registry owner and can change your records, while your own writes revert with <code>!auth</code>. See <a href="/docs/guide/ownership.html#reclaiming-after-a-transfer">Ownership &amp; transfers</a>.</li><li><strong>Update the address record</strong> — a bought name still resolves to the <strong>seller&#39;s</strong> address until you call <code>setAddr</code>. Anyone paying the name in the meantime pays them, not you.</li></ol><p>Then, optionally: set your <a href="/docs/guide/records.html">records</a> and make it your <a href="/docs/guide/primary-name.html">primary name</a>.</p><h2 id="check-the-expiry-before-you-pay" tabindex="-1">Check the expiry before you pay <a class="header-anchor" href="#check-the-expiry-before-you-pay" aria-label="Permalink to &quot;Check the expiry before you pay&quot;">​</a></h2><p>A name&#39;s price should account for how long it&#39;s registered. Buying a name with two weeks left means paying to <a href="/docs/guide/renewals.html">renew</a> almost immediately.</p><p><code>GET /api/v1/domains/:name</code> returns <code>expiresAt</code>, and the app shows it on every listing. Check it before you buy, not after.</p><h2 id="names-that-were-never-registered" tabindex="-1">Names that were never registered <a class="header-anchor" href="#names-that-were-never-registered" aria-label="Permalink to &quot;Names that were never registered&quot;">​</a></h2><p><code>GET /api/v1/domains/:name</code> returns <strong>404</strong> for a name that has never been registered — the indexer has no record to return. That&#39;s a normal response, not an error. Use <code>GET /api/v1/availability?name=…</code> when you want the three-state answer instead.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/registering.html">Registering a name</a> — the full flow.</li><li><a href="/docs/guide/marketplace.html">Marketplace</a> — buying and selling.</li><li><a href="/docs/guide/renewals.html">Renewals &amp; expiry</a> — the grace period in detail.</li></ul>',33)])])}const p=a(i,[["render",n]]);export{u as __pageData,p as default};
